//! Execute only programs generated by this Rust compiler from trusted fixtures.
#[path = "support/native_tools.rs"]
mod native_tools;
use std::{
    fs,
    process::Command,
    sync::atomic::{AtomicU64, Ordering},
    time::{Duration, Instant},
};

fn execute(source: &str, expected: i32) {
    execute_modes(source, expected, true);
}

fn execute_modes(source: &str, expected: i32, compare_vm: bool) {
    execute_sources(source, &[], expected, compare_vm);
}

enum Expectation {
    Exit(i32),
    Trap(jai_vm::Error),
}

fn execute_trap(source: &str, error: jai_vm::Error) {
    execute_sources_inner(source, &[], Expectation::Trap(error), true);
}

fn execute_sources(source: &str, files: &[(&str, &str)], expected: i32, compare_vm: bool) {
    execute_sources_inner(source, files, Expectation::Exit(expected), compare_vm);
}

fn execute_sources_inner(
    source: &str,
    files: &[(&str, &str)],
    expected: Expectation,
    compare_vm: bool,
) {
    static NEXT: AtomicU64 = AtomicU64::new(0);
    struct Scratch(std::path::PathBuf);
    impl Drop for Scratch {
        fn drop(&mut self) {
            let _ = fs::remove_dir_all(&self.0);
        }
    }
    let scratch = Scratch(std::env::temp_dir().join(format!(
        "jai-sequences-{}-{}",
        std::process::id(),
        NEXT.fetch_add(1, Ordering::Relaxed)
    )));
    fs::create_dir(&scratch.0).unwrap();
    let input = scratch.0.join("main.jai");
    fs::write(&input, source).unwrap();
    for (name, source) in files {
        let path = scratch.0.join(name);
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(path, source).unwrap();
    }
    let graph = jai_modules::ModuleGraph::load(
        &input,
        jai_modules::GraphOptions {
            import_dirs: vec![scratch.0.join("modules")],
        },
    )
    .unwrap();
    let target = jai_codegen::target::NativeTarget::new().unwrap();
    let program = jai_sema::resolve_graph_with_options(
        &graph,
        &jai_sema::ResolveOptions {
            layout: Some(target.layout_policy().unwrap()),
            ..Default::default()
        },
        &mut jai_vm::NoEffects,
    )
    .unwrap();
    if compare_vm {
        let mut limits = jai_vm::Limits::default();
        if matches!(
            &expected,
            Expectation::Trap(jai_vm::Error::Limit(
                jai_vm::LimitKind::SequenceTemporaryBytes
            ))
        ) {
            // Isolate the shared backing budget from the VM's independent work cap.
            limits.fuel = 4_000_000;
        }
        let execution = jai_vm::execute(&program, limits);
        match (&expected, execution.outcome) {
            (Expectation::Exit(expected), jai_vm::Outcome::Complete(values)) => {
                assert_eq!(values[0].integer().unwrap().value(), i128::from(*expected))
            }
            (Expectation::Trap(expected), jai_vm::Outcome::Failed(error)) => {
                assert_eq!(&error, expected)
            }
            (_, other) => panic!("unexpected VM outcome: {other:?}"),
        }
    }
    let context = jai_codegen::Context::create();
    let module = jai_codegen::lower_for_target(&context, &program, &target).unwrap();
    let object = scratch.0.join("program.o");
    target.write_object(&module, &object).unwrap();
    let executable = scratch.0.join("program");
    let result = native_tools::clang_command()
        .arg(&object)
        .arg("-o")
        .arg(&executable)
        .output()
        .unwrap();
    assert!(
        result.status.success(),
        "{}\n{}",
        String::from_utf8_lossy(&result.stderr),
        module.print_to_string()
    );
    let mut process = Command::new(&executable).spawn().unwrap();
    let deadline = Instant::now() + Duration::from_secs(5);
    loop {
        if let Some(status) = process.try_wait().unwrap() {
            match &expected {
                Expectation::Exit(expected) => assert_eq!(status.code(), Some(*expected)),
                Expectation::Trap(_) => {
                    assert!(!status.success());
                    #[cfg(unix)]
                    {
                        use std::os::unix::process::ExitStatusExt;
                        assert!(
                            status.signal().is_some(),
                            "native fixture returned instead of trapping: {status:?}"
                        );
                    }
                }
            }
            break;
        }
        if Instant::now() >= deadline {
            process.kill().unwrap();
            process.wait().unwrap();
            panic!("generated sequence fixture timed out");
        }
        std::thread::sleep(Duration::from_millis(5));
    }
}

#[test]
fn fixed_arrays_copy_and_preserve_order() {
    execute(
        "counter := 0; next :: () -> int { counter += 1; return counter; } main :: () -> int { a: [3]int = .[next(), next(), next()]; b := a; a[1] = 9; return b[0]*10 + b[1]*10 + b[2] + a[1]; }",
        42,
    );
}

