#[test]
fn dynamic_array_reallocation_uses_real_libc_storage() {
    execute_modes(
        "malloc :: (size: u64) -> *void #foreign \"malloc\"; realloc :: (memory: *void, size: u64) -> *void #foreign \"realloc\"; free :: (memory: *void) #foreign \"free\"; main :: () -> int { values: [..]int; values.data = cast,no_check(*int) malloc(8); if values.data == null return 1; values.allocated = 1; values.count = 1; values[0] = 20; values.data = cast,no_check(*int) realloc(cast(*void) values.data, 16); if values.data == null return 2; values.allocated = 2; values.count = 2; values[1] = 22; result := values[0] + values[1]; free(cast(*void) values.data); return result; }",
        42,
        false,
    );
}

#[test]
fn dynamic_mutations_preserve_storage_and_reject_invalid_sizes_before_allocating() {
    execute_modes(
        r#"
        realloc :: (memory:*void, size:u64)->*void #foreign "realloc";
        free :: (memory:*void) #foreign "free";
        reserve :: (array:*[..]int, desired:int)->bool {
            maximum := 9223372036854775807 / size_of(int);
            if desired < 0 || desired > maximum return false;
            if array.count < 0 || array.count > array.allocated return false;
            if desired <= array.allocated return true;
            memory := realloc(cast(*void) array.data, cast(u64) desired * cast(u64) size_of(int));
            if memory == null return false;
            array.data = cast,no_check(*int) memory;
            array.allocated = desired;
            return true;
        }
        add :: (array:*[..]int, item:int)->bool {
            maximum := 9223372036854775807 / size_of(int);
            if array.count < 0 || array.count >= maximum return false;
            if array.count >= array.allocated {
                desired := array.count + 1;
                if array.count <= maximum/2 desired = array.count*2;
                if desired < 8 desired = 8;
                if !reserve(array, desired) return false;
            }
            array.data[array.count] = item;
            array.count += 1;
            return true;
        }
        resize :: (array:*[..]int, desired:int)->bool {
            old_count := array.count;
            if !reserve(array, desired) return false;
            array.count = desired;
            for i: old_count..desired-1 array.data[i] = 0;
            return true;
        }
        ordered_remove :: (array:*[..]int, index:int)->bool {
            if index < 0 || index >= array.count return false;
            for i: index..array.count-2 array.data[i] = array.data[i+1];
            array.count -= 1;
            return true;
        }
        reset :: (array:*[..]int) {
            free(cast(*void) array.data);
            array.data = null;
            array.count = 0;
            array.allocated = 0;
        }
        main :: ()->int {
            array:[..]int;
            if ordered_remove(*array, 0) return 1;
            if reserve(*array, -1) return 2;
            if reserve(*array, 9223372036854775807) return 3;
            if !add(*array, 20) || !add(*array, 99) || !add(*array, 22) return 4;
            if !ordered_remove(*array, 1) return 5;
            if ordered_remove(*array, -1) || ordered_remove(*array, array.count) return 6;
            original := array.data;
            if !reserve(*array, array.allocated) || original != array.data return 7;
            if !resize(*array, 4) || array[2] != 0 || array[3] != 0 return 8;
            if !resize(*array, 2) return 9;
            answer := array[0] + array[1];
            reset(*array);
            if array.count != 0 || array.allocated != 0 || array.data != null return 10;
            reset(*array);
            return answer;
        }
        "#,
        42,
        false,
    );
}

fn reject(source: &str, fragment: &str) {
    static NEXT: AtomicU64 = AtomicU64::new(0);
    let path = std::env::temp_dir().join(format!(
        "jai-sequence-reject-{}-{}.jai",
        std::process::id(),
        NEXT.fetch_add(1, Ordering::Relaxed)
    ));
    fs::write(&path, source).unwrap();
    let graph =
        jai_modules::ModuleGraph::load(&path, jai_modules::GraphOptions::default()).unwrap();
    let error = jai_sema::resolve_graph(&graph).unwrap_err();
    fs::remove_file(&path).unwrap();
    assert!(
        error.message.contains(fragment),
        "unexpected diagnostic: {error:?}"
    );
}

#[test]
fn fixed_array_length_mismatches_are_rejected() {
    reject(
        "main :: () -> int { values: [2]int = .[1]; return 0; }",
        "length",
    );
}

#[test]
fn constant_string_names_cannot_be_mutated_through_indexing() {
    reject(
        "value :: \"abc\"; main :: () -> int { value[0] = 4; return 0; }",
        "mutable storage",
    );
}

#[test]
fn runtime_string_descriptors_preserve_immutable_literal_backing() {
    execute_trap(
        "main :: () -> int { value := \"abc\"; value[0] = 4; return 0; }",
        jai_vm::Error::ReadOnlyStorage,
    );
}

#[test]
fn temporary_array_views_cannot_be_returned() {
    reject(
        "bad :: (x: int) -> []int { return .[x, 2]; } main :: () -> int { return 0; }",
        "temporary",
    );
    reject(
        "bad :: (x: int) -> *void { return cast(*void) int.[x,2].data; } main :: () -> int { return 0; }",
        "temporary",
    );
    reject(
        "bad :: (x: int, flag: bool) -> []int { return ifx flag then int.[x,2] else int.[x,3]; } main :: () -> int { return 0; }",
        "temporary",
    );
    reject(
        "View :: struct { data: []int; } bad :: (x: int) -> View { return .{data=.[x,2]}; } main :: () -> int { return 0; }",
        "temporary",
    );
}

